def load_config(config_path):
    """Load monitoring configuration from file and apply settings."""
    try:
        with open(config_path, 'rb') as f:
            config = pickle.load(f)
    except FileNotFoundError:
        print(f"Config file not found: {config_path}")
        return None

    # Apply configuration settings
    if 'dashboard_theme' in config:
        set_theme(config['dashboard_theme'])

    if 'alert_thresholds' in config:
        apply_thresholds(config['alert_thresholds'])

    if 'plugins' in config:
        for plugin_config in config['plugins']:
            initialize_plugin(plugin_config)

    return config

def initialize_plugin(plugin_config):
    """Initialize a monitoring plugin from config."""
    plugin_class = plugin_config['class']
    plugin_args = plugin_config.get('args', {})
    plugin_instance = plugin_class(**plugin_args)
